<?php
use EIPSI\StudyEngine\Longitudinal as L;
/** Six enrollment cases and security boundaries; SMTP is intercepted in the isolated harness. */
function pv_config($mode){$c=L\InitialScreen::defaults();$c['authentication']['verification']=$mode;return $c;}
function pv_complete($p,$f){$id=$f['view']['next_action']['payload']['assessment_execution_id'];pf_dispatch($f,'SUBMIT_ASSESSMENT',array('block_execution_id'=>$id,'responses'=>array('Q_PRE_1'=>3,'Q_PRE_2'=>3)));return pf_runtime()->handle($p['public'],$f['token']);}
function pv_first_intent($f,$purpose,$block){$all=array_values(array_filter(pf_intents($f['access']['execution_id'],$purpose),static function($i)use($block){return $i['block_execution_id']===$block&&$i['state']==='PENDING';}));pe_assert(count($all)===1,'Expected one pending '.$purpose.' intent');return $all[0];}
pf_case('V2 immediate available sends one assessment link which also verifies email',function(){
 $p=pf_publish('03',array('initial_screen'=>pv_config('IMMEDIATE')));$f=pf_enroll($p);pe_assert($f['view']['next_action']['kind']==='EMAIL_VERIFICATION_REQUIRED'&&$f['message']===EIPSI\StudyEngine\Runtime\PublicMessages::text($f['definition'],'email_first_link'),'Missing combined entry notice');$s=pf_owner()->view($f['access']['execution_id']);$block=$s['next_action']['payload']['assessment_execution_id'];$intent=pv_first_intent($f,'VERIFY_PARTICIPANT',$block);pe_assert(count(pf_intents($f['access']['execution_id'],'ASSESSMENT_AVAILABLE'))===0,'Duplicate initial offer');pe_assert(pf_delivery($intent)['success'],'Delivery failed');$mail=end($GLOBALS['m0_mail']);pe_assert($mail['subject']==='Evaluación disponible'&&strpos($mail['message'],'también valida')===false,'Combined email added text outside the template');$r=pf_runtime()->redeem($p['public'],pf_link($mail));pe_assert(pf_participant($r)['verification_state']==='VERIFIED'&&$r['view']['next_action']['kind']==='OPEN_ASSESSMENT','Combined link failed');
});
pf_case('V2 immediate unavailable sends standalone validation and then explains future notices',function(){
 $p=pf_publish('04',array('initial_screen'=>pv_config('IMMEDIATE')));$f=pf_enroll($p);pe_assert(isset($f['entry'])&&strpos($f['message'],'validar tu email')!==false,'No initial verification notice');$i=pv_first_intent($f,'VERIFY_PARTICIPANT',null);pe_assert(pf_delivery($i)['success'],'No validation delivery');$r=pf_runtime()->redeem($p['public'],pf_link(end($GLOBALS['m0_mail'])));pe_assert($r['view']['next_action']['kind']==='WAIT'&&strpos($r['status_message'],'próximas evaluaciones')!==false,'Wrong verified waiting state');$html=(new L\EmailTemplate())->screen($r);pe_assert(strpos($html,'Email validado.')!==false,'Verified message not rendered');pe_assert(strpos($html,'data-notice="email_verified"')<strpos($html,'class="eipsi-initial-card"'),'Notice inside white card');$fresh=pf_runtime()->handle($p['public'],$r['token']);pe_assert(strpos((new L\EmailTemplate())->screen($fresh),'data-notice="email_verified"')===false,'Validation repeated on refresh');$again=pf_runtime()->redeem($p['public'],pf_link(end($GLOBALS['m0_mail'])),$r['token']);pe_assert(!in_array('email_verified',$again['notice_keys']??array(),true),'Validation repeated on same link');$newCap=pf_mint($again,'VERIFY_PARTICIPANT');$later=pf_runtime()->redeem($p['public'],$newCap,$again['token']);pe_assert(!in_array('email_verified',$later['notice_keys']??array(),true),'Validation repeated on another link');
});
pf_case('V2 second available corrects email without extra mail and verifies through the later opportunity',function(){
 $saved=$GLOBALS['pf_now'];try{$p=pf_publish('03',array('initial_screen'=>pv_config('AFTER_FIRST'),'provisional_hours'=>72));$f=pf_enroll($p);$r=pv_complete($p,$f);pe_assert(!$r['email_confirmation']['requires_link'],'Direct review requires an extra link');$count=count($GLOBALS['m0_mail']);$r=pi_request($p,$r,'after-first-corrected@example.test');pe_assert(!isset($r['email_confirmation'])&&pf_participant($r)['email']==='after-first-corrected@example.test'&&count($GLOBALS['m0_mail'])===$count,'Direct correction sent mail or lost identity');$GLOBALS['pf_now']=gmdate('Y-m-d\TH:i:s\Z',strtotime($saved)+86400);$next=pf_runtime()->handle($p['public'],$r['token']);pe_assert($next['view']['next_action']['kind']==='EMAIL_VERIFICATION_REQUIRED','Later evaluation bypassed validation');$intents=pf_intents($r['access']['execution_id'],'VERIFY_PARTICIPANT');$available=array_values(array_filter($intents,static function($i){return $i['trigger_at']<=pf_clock()->mysql();}));pe_assert(count($available)>0,'No later verification notice');pf_delivery(end($available));$mail=end($GLOBALS['m0_mail']);pe_assert(in_array('after-first-corrected@example.test',(array)$mail['to'],true),'Later mail sent to old address');$done=pf_runtime()->redeem($p['public'],pf_link($mail));pe_assert(pf_participant($done)['verification_state']==='VERIFIED'&&$done['view']['next_action']['kind']==='OPEN_ASSESSMENT','Later link did not validate');}finally{$GLOBALS['pf_now']=$saved;}
});
pf_case('V2 second unavailable validates immediately and keeps the gate when first becomes available',function(){
 $saved=$GLOBALS['pf_now'];try{$p=pf_publish('04',array('initial_screen'=>pv_config('AFTER_FIRST'),'provisional_hours'=>72));$f=pf_enroll($p);$i=pv_first_intent($f,'VERIFY_PARTICIPANT',null);pe_assert(isset($f['entry'])&&pf_delivery($i)['success'],'No early verification');$cap=pf_link(end($GLOBALS['m0_mail']));$v=pf_owner()->view($f['access']['execution_id']);$times=array_column($v['snapshot']['instances'],'available_at');$times=array_values(array_filter($times,static function($t)use($saved){return $t!==null&&$t>$saved;}));sort($times);$GLOBALS['pf_now']=$times[0];$waiting=pf_runtime()->handle($p['public'],$f['token']);pe_assert($waiting['view']['next_action']['kind']==='EMAIL_VERIFICATION_REQUIRED','Gate changed after clock advance');$r=pf_runtime()->redeem($p['public'],$cap);pe_assert(pf_participant($r)['verification_state']==='VERIFIED'&&$r['view']['next_action']['kind']==='OPEN_ASSESSMENT','Early verification cannot open first');}finally{$GLOBALS['pf_now']=$saved;}
});
pf_case('V2 never available reviews and corrects directly without sending validation or losing responses',function(){
 $p=pf_publish('03',array('initial_screen'=>pv_config('NEVER')));$f=pf_enroll($p);$old=pf_participant($f);$cap=pf_mint($f,'VERIFY_PARTICIPANT');$r=pv_complete($p,$f);pe_assert(!$r['email_confirmation']['requires_link'],'NEVER requests proof');$r=pi_request($p,$r,'NEVER-CORRECTED@example.test','NEVER_CORRECT');$now=pf_participant($r);pe_assert($now['id']===$old['id']&&$now['email']==='never-corrected@example.test'&&$now['verification_state']==='UNVERIFIED','Correction changed identity or verified without proof');pe_assert($r['view']['next_action']['kind']==='WAIT'&&strpos($r['status_message'],'próximas evaluaciones')!==false,'No future notice');pe_assert(count(pf_intents($f['access']['execution_id'],'VERIFY_PARTICIPANT'))===0,'NEVER sent validation');pe_assert(count((new EIPSI\StudyEngine\Persistence\SubmissionJournalRepository(pf_db()))->list($f['access']['execution_id']))===1,'Lost first response');pe_reject(function()use($p,$cap){pf_runtime()->redeem($p['public'],$cap);},'ACCESS_REQUIRED');$again=pf_runtime()->handle($p['public'],$f['token']);pe_assert($again['view']['next_action']['kind']==='WAIT','Current session lost');
});
pf_case('V2 never unavailable sends no standalone validation and future assessment email verifies',function(){
 $saved=$GLOBALS['pf_now'];try{$p=pf_publish('04',array('initial_screen'=>pv_config('NEVER'),'provisional_hours'=>72));$f=pf_enroll($p);pe_assert($f['view']['next_action']['kind']==='WAIT'&&count(pf_intents($f['access']['execution_id'],'VERIFY_PARTICIPANT'))===0&&strpos($f['status_message'],'próximas evaluaciones')!==false,'Wrong NEVER waiting state');$all=pf_intents($f['access']['execution_id'],'ASSESSMENT_AVAILABLE');pe_assert(count($all)===7,'Legacy VERIFIED_ONLY suppressed future offers');usort($all,static function($a,$b){return strcmp($a['trigger_at'],$b['trigger_at']);});$GLOBALS['pf_now']=gmdate('Y-m-d\TH:i:s\Z',strtotime($all[0]['trigger_at'].' UTC'));pe_assert(pf_delivery($all[0])['success'],'Future offer failed');$r=pf_runtime()->redeem($p['public'],pf_link(end($GLOBALS['m0_mail'])));pe_assert(pf_participant($r)['verification_state']==='VERIFIED'&&$r['view']['next_action']['kind']==='OPEN_ASSESSMENT','Future offer not verification');}finally{$GLOBALS['pf_now']=$saved;}
});
pf_case('V2 assessment window expiry preserves link verification without reopening the assessment',function(){
 $saved=$GLOBALS['pf_now'];try{$p=pf_publish('03',array('initial_screen'=>pv_config('IMMEDIATE')));$f=pf_enroll($p);$v=pf_owner()->view($f['access']['execution_id']);$block=$v['next_action']['payload']['assessment_execution_id'];$i=pv_first_intent($f,'VERIFY_PARTICIPANT',$block);pe_assert(pf_delivery($i)['success'],'No first offer');$cap=pf_link(end($GLOBALS['m0_mail']));$due=$v['snapshot']['instances'][$block]['due_at'];$GLOBALS['pf_now']=gmdate('Y-m-d\TH:i:s\Z',strtotime($due)+1);$r=pf_runtime()->redeem($p['public'],$cap);pe_assert(pf_participant($r)['verification_state']==='VERIFIED'&&$r['view']['snapshot']['instances'][$block]['state']==='EXPIRED'&&$r['view']['next_action']['kind']!=='OPEN_ASSESSMENT','Expired assessment reopened or email not verified');pe_assert(strpos($r['status_message'],'ya venció')!==false,'No expiry notice');pe_assert(pf_owner()->view($f['access']['execution_id'])['snapshot']['instances'][$block]['due_at']===$due,'Deadline extended');}finally{$GLOBALS['pf_now']=$saved;}
});
pf_case('V2 expired or revoked security credentials cannot verify email',function(){
 $saved=$GLOBALS['pf_now'];try{$p=pf_publish(null,array('initial_screen'=>pv_config('NEVER')));$f=pf_enroll($p);$cap=pf_mint($f,'ASSESSMENT_AVAILABLE');$GLOBALS['pf_now']=gmdate('Y-m-d\TH:i:s\Z',strtotime($saved)+49*3600);pe_reject(function()use($p,$cap){pf_runtime()->redeem($p['public'],$cap);},'ACCESS_REQUIRED');pe_assert(pf_participant($f)['verification_state']==='UNVERIFIED','Expired bearer verified');$GLOBALS['pf_now']=$saved;(new L\Identity(pf_db(),pf_clock()))->revokeParticipant($f['access']['participant_id']);pe_reject(function()use($p,$cap){pf_runtime()->redeem($p['public'],$cap);},'ACCESS_REQUIRED');}finally{$GLOBALS['pf_now']=$saved;}
});
pf_case('V2 no-proof correction rejects another participant and remains idempotent',function(){
 $p=pf_publish('03',array('initial_screen'=>pv_config('NEVER')));$f=pf_enroll($p);$other=pf_enroll($p,'v2-taken@example.test');$r=pv_complete($p,$f);pe_reject(function()use($p,$r){pi_request($p,$r,'v2-taken@example.test');},'EMAIL_ALREADY_ENROLLED');$email=pf_participant($r)['email'];$done=pi_request($p,$r,$email,'V2_REVIEW_ONCE');$again=pi_request($p,$r,$email,'V2_REVIEW_ONCE');pe_assert($done['view']['revision']===$again['view']['revision']&&pf_participant($again)['verification_state']==='UNVERIFIED','Review replay mutates science or verifies');
});
pf_case('V2 HTTP redemption renders verification notice without exposing bearer in the final page',function(){
 $p=pf_publish('04',array('initial_screen'=>pv_config('NEVER')));$f=pf_enroll($p);$cap=pf_http_cap($f,'ASSESSMENT_REMINDER');$r=pf_http($p['public'],array(),null,$cap);pe_assert($r['status']===200&&strpos($r['data']['html'],'Email validado.')!==false&&strpos($r['data']['html'],$cap)===false,'HTTP verification notice or token leak');
});
pf_case('V2 explicit verification anchors respect all three admission modes without fabricating verification',function(){
 foreach(array('IMMEDIATE','AFTER_FIRST','NEVER') as $mode){$d=L\Configuration::apply(pe_definition(),array('initial_screen'=>pv_config($mode)));foreach($d['nodes'] as &$n)if($n['id']==='E_ASSESSMENT'){$n['schedule']['anchor']='PARTICIPANT_VERIFIED';$n['schedule']['anchor_ref']=null;$n['schedule']['occurrence_selector']=null;}unset($n);$p=pe_publish('simple',false,$d);$f=pf_enroll($p);$intents=pf_intents($f['access']['execution_id'],'VERIFY_PARTICIPANT');pe_assert(count($intents)===($mode==='NEVER'?0:1),'Initial proof request contradicts '.$mode);pe_assert(pf_participant($f)['verification_state']==='UNVERIFIED','Anchor fabricated proof');if($mode==='NEVER'){$entry=pf_runtime()->handle($p['public']);pf_runtime()->handle($p['public'],$entry['token'],array('action'=>'enroll','command_id'=>'EXPLICIT_RECOVERY','csrf'=>$entry['csrf'],'email'=>pf_participant($f)['email']));$intent=pv_first_intent($f,'VERIFY_PARTICIPANT',null);}else $intent=$intents[0];pe_assert(pf_delivery($intent)['success'],'Explicit proof delivery failed');$done=pf_runtime()->redeem($p['public'],pf_link(end($GLOBALS['m0_mail'])));pe_assert($done['view']['next_action']['kind']==='OPEN_ASSESSMENT'&&pf_participant($done)['verification_state']==='VERIFIED','Real proof did not satisfy anchor');}
});
pf_case('V2 future verification anchor does not request early validation when first assessment is already available',function(){
 $d=pd_definition('03');$d['study']=array('logical_id'=>'STUDY_V2_ANCHOR_'.bin2hex(random_bytes(5)),'public_id'=>'PUBLIC_V2_ANCHOR_'.bin2hex(random_bytes(5)));$d=L\Configuration::apply($d,array('initial_screen'=>pv_config('AFTER_FIRST')));$d['protocol_metadata']['content_adapter']='P1E_V1';$d['protocol_metadata']['storage_mode']='WORDPRESS_LOCAL';foreach($d['nodes'] as &$n){if($n['id']==='E_POST'){$n['schedule']['anchor']='PARTICIPANT_VERIFIED';$n['schedule']['anchor_ref']=null;$n['schedule']['occurrence_selector']=null;}if($n['kind']==='QUESTION'){$n['content']['snapshot']=EIPSI\StudyEngine\Contracts\Canonical::json(array('label'=>$n['id'],'helper'=>'','format'=>'text','widget'=>'eipsi/campo-texto','step'=>null));$n['content']['sha256']=hash('sha256',$n['content']['snapshot']);}}unset($n);$p=pe_publish('simple',false,$d);$f=pf_enroll($p);pe_assert($f['view']['next_action']['kind']==='OPEN_ASSESSMENT'&&count(pf_intents($f['access']['execution_id'],'VERIFY_PARTICIPANT'))===0,'Future anchor sent premature validation');$r=pv_complete($p,$f);pe_assert(!$r['email_confirmation']['requires_link'],'Direct correction demands a new standalone link');
});
pf_case('V2 HTTP expired security link shows Initial Screen with a red notice and cannot validate email',function(){
 $p=pf_publish(null,array('initial_screen'=>pv_config('NEVER')));$f=pf_enroll($p);$cap=pf_http_cap($f,'ASSESSMENT_AVAILABLE');pf_db()->transactional(function()use($cap){pf_db()->update('access_capabilities',array('expires_at'=>gmdate('Y-m-d H:i:s',strtotime($GLOBALS['pf_now'])-1)),pf_db()->prepare('token_hash=%s',hash('sha256',$cap)));});$r=pf_http($p['public'],array(),null,$cap,array(),false);pe_assert($r['status']===403&&strpos($r['body'],'solicitar un nuevo enlace')===false&&strpos($r['data']['html']??'','data-unavailable="1"')!==false&&strpos($r['data']['html'],'name="email"')!==false&&strpos($r['data']['html'],'data-notice="unavailable_title" role="alert"')!==false&&strpos($r['body'],$cap)===false,'No secure recovery route: '.$r['body']);pe_assert(pf_participant($f)['verification_state']==='UNVERIFIED','Expired link verified email');
