pf_case('V2 direct first access cancels redundant availability mail even under SEND while future notices remain available',function(){
 foreach(array('NEVER','AFTER_FIRST') as $mode){$p=pf_publish('03',array('initial_screen'=>pv_config($mode),'immediate_availability_policy'=>'SEND'));$f=pf_enroll($p);$block=$f['view']['next_action']['payload']['assessment_execution_id'];$intent=pv_first_intent($f,'ASSESSMENT_AVAILABLE',$block);$before=count($GLOBALS['m0_mail']);$result=pf_delivery($intent);$after=pf_db()->row(pf_db()->prepare('SELECT state,cancel_reason FROM '.pf_db()->table('notification_intents').' WHERE id=%s',$intent['id']));pe_assert($result['success']&&$after['state']==='CANCELLED'&&$after['cancel_reason']==='INITIAL_DIRECT_ACCESS','Redundant initial notice not cancelled: '.json_encode($after));pe_assert(count($GLOBALS['m0_mail'])===$before,'Direct access sent duplicate mail');}
 $c=pv_config('IMMEDIATE');pe_assert(!L\InitialScreen::reviewRequired(array('initial_screen'=>$c)),'Immediate demands another review');$c=pv_config('NEVER');$c['authentication']['confirm_after_first']=false;pe_assert(!L\InitialScreen::reviewRequired(array('initial_screen'=>$c)),'Disabled review remains required');
});

pf_case('V2 first assessment entered through an email link never requests another email review',function(){foreach(array('NEVER','AFTER_FIRST') as $mode){$p=pf_publish('03',array('initial_screen'=>pv_config($mode)));$f=pf_enroll($p);$f=pf_runtime()->redeem($p['public'],pf_mint($f,'VERIFY_PARTICIPANT'));$r=pv_complete($p,$f);pe_assert(!isset($r['email_confirmation'])&&pf_participant($r)['verification_state']==='VERIFIED','Verified link still requires address review');}});

pf_case('V2 changed review email requires explicit acknowledgement before identity changes',function(){
