pf_case('Unverified email uses one validation link and verified reentry never sends it again',function(){
 $c=pv_config('NEVER');$c['templates']['VERIFY_PARTICIPANT']=array('subject'=>'Validación de ingreso','html'=>'<p>Confirmá tu email.</p><p><a href="[direct_link]">Validar ingreso</a></p>');$p=pf_publish('03',array('initial_screen'=>$c,'email_enabled'=>false));$f=pf_enroll($p,'returning@example.test');$entry=pf_runtime()->handle($p['public']);$req=array('action'=>'enroll','command_id'=>'VALIDATE_RETURN','csrf'=>$entry['csrf'],'email'=>'RETURNING@EXAMPLE.TEST');$reply=pf_runtime()->handle($p['public'],$entry['token'],$req);pe_assert(isset($reply['entry'])&&!isset($reply['access'])&&pf_participant($f)['verification_state']==='UNVERIFIED','Email entry granted authority');$rows=pf_intents($f['access']['execution_id'],'VERIFY_PARTICIPANT');pe_assert(count($rows)===1&&$rows[0]['purpose']==='VERIFY_PARTICIPANT','Wrong email type');pf_runtime()->handle($p['public'],$entry['token'],$req);pe_assert(count(pf_intents($f['access']['execution_id'],'VERIFY_PARTICIPANT'))===1,'Retried request duplicated mail');pe_assert(pf_delivery($rows[0])['success'],'Validation delivery failed');$mail=end($GLOBALS['m0_mail']);pe_assert($mail['subject']==='Validación de ingreso','Ignored configured validation template');$done=pf_runtime()->redeem($p['public'],pf_link($mail));pe_assert($done['access']['execution_id']===$f['access']['execution_id']&&$done['access']['kind']==='AUTHENTICATED'&&pf_participant($done)['verification_state']==='VERIFIED','Validation lost participation');$again=pf_runtime()->handle($p['public']);$req['csrf']=$again['csrf'];$req['command_id']='VALIDATE_AGAIN';$return=pf_runtime()->handle($p['public'],$again['token'],$req);$rows=pf_intents($f['access']['execution_id'],'VERIFY_PARTICIPANT');pe_assert(count($rows)===1&&isset($return['access'])&&$return['access']['execution_id']===$f['access']['execution_id'],'Verified email requested another validation link');
