pf_case('Retired email types reject creation and old queued deliveries are cancelled without SMTP',function(){
 $p=pf_publish('03',array('initial_screen'=>pv_config('NEVER')));$f=pf_enroll($p);$s=pf_owner()->view($f['access']['execution_id'])['snapshot'];foreach(array('ACCESS','WITHDRAWAL_OPTIONS') as $purpose){pe_reject(function()use($f,$s,$purpose){(new L\NotificationScheduler(pf_db()))->authentication($f['access']['execution_id'],$purpose,'RETIRED',$s);},'INVALID_AUTHENTICATION_INTENT');$id=pf_db()->transactional(function()use($f,$s,$purpose){return (new L\NotificationScheduler(pf_db()))->authentication($f['access']['execution_id'],'VERIFY_PARTICIPANT','OLD_QUEUE_'.$purpose,$s);});pf_db()->transactional(function()use($id,$purpose){pf_db()->update('notification_intents',array('purpose'=>$purpose),pf_db()->prepare('id=%s',$id));});$row=pf_db()->row(pf_db()->prepare('SELECT * FROM '.pf_db()->table('notification_intents').' WHERE id=%s',$id));$before=count($GLOBALS['m0_mail']);pe_assert(pf_delivery($row)['success'],'Old queued job unresolved');$row=pf_db()->row(pf_db()->prepare('SELECT * FROM '.pf_db()->table('notification_intents').' WHERE id=%s',$id));pe_assert($row['state']==='CANCELLED'&&count($GLOBALS['m0_mail'])===$before,'Retired email delivered');$values=array_fill_keys(array('study_name','assessment_name','available_time','due_time','direct_link','communications_link','withdrawal_link'),'');pe_reject(function()use($purpose,$values){(new L\EmailTemplate())->render($purpose,$values);},'UNKNOWN_EMAIL_TEMPLATE');}pe_reject(function()use($f){pf_mint($f,'ACCESS');},'INVALID_CAPABILITY_SCOPE');
});

pf_case('Waiting notice belongs to the current response and landing reload never restores study identity',function(){
 list($p,$h,$cookies)=pf_http_enroll('04',array('initial_screen'=>pv_config('NEVER')));pe_assert($h['data']['state']==='WAIT','Not waiting');$html=$h['data']['html'];pe_assert(strpos($html,'Consultar disponibilidad')===false&&strpos($html,'Pantalla Inicial')===false&&strpos($html,'Cerrar sesión')===false&&strpos($html,'Próxima disponibilidad:')!==false,'Wrong waiting controls or lost schedule');$f=pf_http_frame($p,$h,$cookies);$before=(new EIPSI\StudyEngine\Persistence\StudyExecutionRepository(pf_db()))->find($f['access']['execution_id']);$r=wp_remote_get('http://127.0.0.1/?eipsi_study='.rawurlencode($p['public']).'&eipsi_initial=1',array('timeout'=>20,'redirection'=>0,'headers'=>array('Host'=>'127.0.0.1:18080','Accept'=>'application/json'),'cookies'=>$cookies));pe_assert(!is_wp_error($r)&&wp_remote_retrieve_response_code($r)===200,'Reload failed');$data=json_decode(wp_remote_retrieve_body($r),true);pe_assert($data['state']==='EMAIL_ENTRY'&&strpos($data['html'],'id="study-email"')!==false,'Reload did not show Initial Screen');foreach(array('wait_title','email_future_notices','next_time','email_verified') as $key)pe_assert(strpos($data['html'],'data-notice="'.$key.'"')===false,'Sticky notice: '.$key);pe_assert(preg_match('/id="study-email"[^>]*value=""/',$data['html'])===1,'Study email restored from cookie');$plain=pf_http($p['public'],$cookies);pe_assert($plain['data']['state']==='EMAIL_ENTRY'&&strpos($plain['data']['html'],'data-notice="next_time"')===false,'Plain study URL restored identity');$session=(new L\Identity(pf_db(),new L\Clock()))->recover($p['public'],$f['token']);$after=(new EIPSI\StudyEngine\Persistence\StudyExecutionRepository(pf_db()))->find($f['access']['execution_id']);pe_assert($session&&$session['id']===$f['access']['id']&&$after['checkpoint_hash']===$before['checkpoint_hash'],'Reload changed session or study progress');
});

pf_case('HTTP withdrawal rejects an unrelated email in its own dialog and allows correction without losing the session',function(){
 $c=pv_config('NEVER');$c['withdrawal']['typed_confirmation']=true;list($p,$h,$cookies,$email)=pf_http_enroll('03',array('initial_screen'=>$c));$f=pf_http_frame($p,$h,$cookies);$r=array('action'=>'withdraw','command_id'=>'HTTP_WRONG_WITHDRAWAL','csrf'=>$f['csrf'],'email'=>'missing@example.test','mode'=>'RETAIN_FOR_ANALYSIS','confirmation_text'=>L\InitialScreen::withdrawalPhrase($c['withdrawal'],'RETAIN_FOR_ANALYSIS'),'expected_revision'=>$f['view']['revision']);$before=pf_intents($f['access']['execution_id']);$bad=pf_http($p['public'],$cookies,$r);$html=$bad['data']['html']??'';pe_assert($bad['status']===422&&strpos($html,'data-withdrawal-error="1"')!==false&&strpos($html,'value="missing@example.test"')!==false,'Wrong email lost the abandonment dialog: '.$bad['body']);pe_assert((bool)pf_participant($f)['active']&&pf_owner()->view($f['access']['execution_id'])['snapshot']['withdrawal']===null,'Wrong email withdrew a participant');$r['command_id']='HTTP_CORRECTED_WITHDRAWAL';$r['email']=$email;$good=pf_http($p['public'],$cookies,$r);pe_assert($good['status']===200&&pf_owner()->view($f['access']['execution_id'])['snapshot']['withdrawal']['mode']==='RETAIN_FOR_ANALYSIS','Correction failed: '.$good['body']);pe_assert(count(pf_intents($f['access']['execution_id']))===count($before),'Withdrawal generated email');
});

pf_case('Email withdrawal targets B with cookie A and also works without any participant session',function(){
 foreach(array('RETAIN_FOR_ANALYSIS','DO_NOT_USE') as $mode){
  $c=pv_config('NEVER');$c['withdrawal']['typed_confirmation']=true;$p=pf_publish('03',array('initial_screen'=>$c));$a=pf_enroll($p,'owner-a@example.test');$b=pf_enroll($p,'target-b@example.test');$otherStudy=pf_publish('03',array('initial_screen'=>$c));$other=pf_enroll($otherStudy,'target-b@example.test');
  $entry=pf_runtime()->initialFrame($p['public'],$mode==='RETAIN_FOR_ANALYSIS'?$a['token']:null);$token=$entry['token'];$lookup=array('action'=>'withdrawal_lookup','command_id'=>'LOOKUP_EMAIL_TARGET','csrf'=>$entry['csrf'],'email'=>' TARGET-B@EXAMPLE.TEST ');$check=pf_runtime()->handle($p['public'],$token,$lookup);pe_assert(isset($check['withdrawal_check']['revision']),'Email lookup required a participant session');
  $request=array('action'=>'withdraw','command_id'=>'EMAIL_TARGET_WITHDRAW','csrf'=>$entry['csrf'],'email'=>$lookup['email'],'mode'=>$mode,'expected_revision'=>$check['withdrawal_check']['revision'],'confirmation_text'=>L\InitialScreen::withdrawalPhrase($c['withdrawal'],$mode));$count=count($GLOBALS['m0_mail']);$done=pf_runtime()->handle($p['public'],$token,$request);pe_assert($done['withdrawal']['mode']===$mode,'Wrong withdrawal policy');$record=(new \EIPSI\StudyEngine\Persistence\WithdrawalRepository(pf_db()))->find($b['access']['execution_id']);pe_assert($record&&$record['source']==='EMAIL_ENTRY','Wrong email target/source');pe_assert((new \EIPSI\StudyEngine\Persistence\WithdrawalRepository(pf_db()))->find($a['access']['execution_id'])===null&&(new \EIPSI\StudyEngine\Persistence\WithdrawalRepository(pf_db()))->find($other['access']['execution_id'])===null,'Cookie owner or another Study was withdrawn');pe_assert((bool)pf_participant($a)['active']&&(bool)pf_participant($other)['active'],'Unrelated participant changed');pe_assert(count($GLOBALS['m0_mail'])===$count,'Unrequested email');
 }
});
pf_case('Email withdrawal lookup is Study-scoped and rejects posted participant identities',function(){
 $c=pv_config('NEVER');$p=pf_publish('03',array('initial_screen'=>$c));$otherStudy=pf_publish('03',array('initial_screen'=>$c));$other=pf_enroll($otherStudy,'foreign@example.test');$entry=pf_runtime()->initialFrame($p['public']);$request=array('action'=>'withdrawal_lookup','command_id'=>'MISSING_TARGET','csrf'=>$entry['csrf'],'email'=>'foreign@example.test');pe_reject(function()use($p,$entry,$request){pf_runtime()->handle($p['public'],$entry['token'],$request);},'WITHDRAWAL_EMAIL_NOT_FOUND');$request['participant_id']=$other['access']['participant_id'];pe_reject(function()use($p,$entry,$request){pf_runtime()->handle($p['public'],$entry['token'],$request);},'UNKNOWN_FIELD');pe_assert((bool)pf_participant($other)['active'],'Foreign participant changed');
