pf_case('HTTP withdrawal revision errors never restore the cookie owner into the Study landing',function(){
 $c=pv_config('NEVER');$c['withdrawal']['typed_confirmation']=true;list($p,$h,$cookies,$emailA)=pf_http_enroll('03',array('initial_screen'=>$c));$b=pf_enroll($p,'email-b-conflict@example.test');$token=$cookies[0]->value;$request=array('action'=>'withdrawal_lookup','command_id'=>'HTTP_EMAIL_LOOKUP_B','csrf'=>L\Identity::csrf($p['public'],$token),'email'=>'email-b-conflict@example.test');$lookup=pf_http($p['public'],$cookies,$request);pe_assert($lookup['status']===200&&isset($lookup['data']['withdrawal_check']['revision']),'Cookie A blocked B lookup');$request['action']='withdraw';$request['command_id']='HTTP_EMAIL_CONFLICT_B';$request['mode']='RETAIN_FOR_ANALYSIS';$request['expected_revision']=$lookup['data']['withdrawal_check']['revision']+100;$request['confirmation_text']=L\InitialScreen::withdrawalPhrase($c['withdrawal'],'RETAIN_FOR_ANALYSIS');$bad=pf_http($p['public'],$cookies,$request);$html=$bad['data']['html']??'';pe_assert($bad['status']===409&&strpos($html,'data-withdrawal-error="1"')!==false&&strpos($html,'value="email-b-conflict@example.test"')!==false,'Wrong recovery context');pe_assert(strpos($html,'data-notice="next_time"')===false&&preg_match('/id="study-email"[^>]*value=""/',$html)===1,'Error recovered cookie owner');pe_assert((bool)pf_participant($b)['active'],'Conflict withdrew B');
