pf_case('Verified email entry reports current WAIT or OPEN without validation mail or reliance on an earlier cookie',function(){
 $GLOBALS['pf_native_transport']=true;
 // Keep the diary fixture before its 20:00 local window, regardless of the wall-clock hour.
 $saved=$GLOBALS['pf_now'];$GLOBALS['pf_now']=gmdate('Y-m-d\T12:00:00\Z');try{foreach(array('04','03') as $fixture){
  $p=pf_publish($fixture,array('initial_screen'=>pv_config('NEVER')));$f=pf_enroll($p,'verified-target@example.test');$verified=pf_runtime()->redeem($p['public'],pf_mint($f,'VERIFY_PARTICIPANT'));$other=pf_enroll($p,'other-browser-owner@example.test');$before=count(pf_intents($f['access']['execution_id'],'VERIFY_PARTICIPANT'));
  foreach(array(array(),array(new WP_Http_Cookie(array('name'=>L\Identity::cookieName($p['public']),'value'=>$other['token'])))) as $jar){
   $entry=pf_http($p['public'],$jar);$request=pe_http_request($entry,'enroll');$request['email']='VERIFIED-TARGET@EXAMPLE.TEST';$reply=pf_http($p['public'],$entry['cookies']?:$jar,$request);$expected=$fixture==='04'?'WAIT':'OPEN_ASSESSMENT';pe_assert($reply['status']===200&&$reply['data']['state']===$expected,'Wrong verified-email state: '.$reply['body']);$html=$reply['data']['html'];pe_assert(strpos($html,'Si corresponde')===false&&strpos($html,'data-notice="email_validation_sent"')===false&&strpos($html,'data-notice="email_verified"')===false,'Redundant validation message');
   if($expected==='WAIT')foreach(array('wait_title','next_time') as $key)pe_assert(strpos($html,'data-notice="'.$key.'"')!==false,'No availability status: '.$key);
   $bound=pf_http_frame($p,$reply,$reply['cookies']);pe_assert($bound['access']['execution_id']===$f['access']['execution_id'],'Cookie selected the wrong participant');
  }
  pe_assert(count(pf_intents($f['access']['execution_id'],'VERIFY_PARTICIPANT'))===$before,'Verified entry queued another validation email');
 }}finally{$GLOBALS['pf_now']=$saved;}
 $GLOBALS['pf_native_transport']=false;
});
